def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    import datetime
    if not isinstance(nanoseconds, int):
        raise TypeError("nanoseconds must be an integer")
    try:
        # Convert nanoseconds to microseconds for timedelta
        microseconds = nanoseconds // 1000
        dt = datetime.datetime(1970, 1, 1, tzinfo=tz) + datetime.timedelta(microseconds=microseconds)
        return dt.time()
    except Exception as exc:
        raise ValueError("Invalid input for hydrate_time") from exc

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: datetime.time
    :return: str or None
    """
    # Return None for a missing value
    if value is None:
        return None

    # Ensure the value has the expected interface
    if not hasattr(value, "strftime"):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

    try:
        # Include timezone offset if present
        if getattr(value, "tzinfo", None) is not None:
            return value.strftime("%H:%M:%S%z")
        return value.strftime("%H:%M:%S")
    except Exception as exc:
        raise TypeError("Failed to dehydrate time value") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        # Handle tuple or list with two elements
        if isinstance(value, (tuple, list)) and len(value) == 2:
            x, y = value
            return {"x": x, "y": y}
        # Handle dict with 'x' and 'y' keys
        if isinstance(value, dict) and "x" in value and "y" in value:
            return {"x": value["x"], "y": value["y"]}
        # Handle objects with x and y attributes
