    # If already an integer, return as int
    if isinstance(n, int):
        return n
    # Compute floor and fractional part
    floor_val = math.floor(n)
    frac = n - floor_val
    # Determine rounding
    if frac < 0.5:
        return int(floor_val)
    elif frac > 0.5:
        return int(floor_val + 1)
    else:  # frac == 0.5
        # If floor is even, return floor; else return floor + 1
        if floor_val % 2 == 0:
            return int(floor_val)
        else:
            return int(floor_val + 1)

