def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters
    ----------
    cache : mapping-like
        Object that supports ``__contains__``, ``__getitem__`` and ``__setitem__``.
    key : callable or any, optional
        Function that generates a cache key from ``(args, kwargs)`` or a static key.
        If ``None`` or not callable, a default key based on the arguments is used.
    lock : object, optional
        Optional lock object with ``acquire`` and ``release`` methods for thread safety.

    Returns
    -------
    decorator : callable
        Decorator that memoizes the wrapped function.
    """
    import functools

    if cache is None:
        raise ValueError("cache must be a mapping-like object")

    # Default key function if none provided or not callable
    def default_key(args, kwargs):
        return (args, tuple(sorted(kwargs.items())))

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Determine cache key
            try:
                if callable(key):
                    try:
                        k = key(args, kwargs)
                    except TypeError:
                        k = key(*args, **kwargs)
                else:
                    k = key
                if k is None:
                    k = default_key(args, kwargs)
            except Exception:
                # Fallback to default key if key function fails
                k = default_key(args, kwargs)

            # Attempt to retrieve from cache
            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
            except Exception:
                # If cache lookup fails, ignore and recompute
                pass
            finally:
                if lock:
                    lock.release()

            # Compute result and store in cache
            result = func(*args, **kwargs)

            if lock:
                lock.acquire()
            try:
                cache[k] = result
            except Exception:
                # If cache set fails, ignore
                pass
            finally:
                if lock:
                    lock.release()

            return result

        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import functools
    from collections import OrderedDict

    def decorator(func):
        # If caching is disabled by maxsize or ttl, just return the original function
        if not maxsize or ttl <= 0:
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        cache = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key from args and kwargs
            key = args
            if kwargs:
                # Sort kwargs to ensure deterministic ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types of positional arguments
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    # Include types of keyword argument values
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))

            now = timer()
            # Check if key is in cache and not expired
            if key in cache:
                value, expire = cache[key]
                if expire > now:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer or None")
    if maxsize is not None and maxsize < 0:
        maxsize = None  # treat negative as unlimited

    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys in LRU order, oldest first
        hits = 0
        misses = 0

        def make_key(args, kwargs):
            if typed:
                key_args = tuple((arg, type(arg)) for arg in args)
                key_kwargs = tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
            else:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))
            return (key_args, key_kwargs)

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            try:
                key = make_key(args, kwargs)
            except TypeError:
                # Unhashable arguments; do not cache
                return user_function(*args, **kwargs)

            if key in cache:
                # Move key to end to mark as recently used
                order.remove(key)
                order.append(key)
                hits += 1
                return cache[key]
            else:
                result = user_function(*args, **kwargs)
                cache[key] = result
                order.append(key)
                misses += 1
                if maxsize is not None and len(order) > maxsize:
                    oldest = order.pop(0)
                    del cache[oldest]
                return result

        def cache_info():
            """Report cache statistics"""
            return {
                'hits': hits,
                'misses': misses,
                'maxsize': maxsize,
                'currsize': len(order)
            }

        def cache_clear():
            """Clear the cache and cache statistics"""
            nonlocal hits, misses
            cache.clear()
            order.clear()
            hits = 0
            misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non‑negative integer")
    def decorator(func):
        cache = {}
        freq = {}
        min_freq = 0
        def wrapper(*args, **kwargs):
            nonlocal min_freq
            # Build cache key
            try:
                if typed:
                    key = (args,
                           tuple(sorted(kwargs.items())),
                           tuple(type(arg) for arg in args),
                           tuple(type(v) for v in kwargs.values()))
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except Exception:
                # If key cannot be built (e.g., unhashable), skip caching
                return func(*args, **kwargs)
            if maxsize == 0:
                return func(*args, **kwargs)
            if key in cache:
                # Increment frequency
                freq[key] += 1
                if freq[key] > min_freq:
                    min_freq = freq[key]
                return cache[key]
            # Compute result
            result = func(*args, **kwargs)
            # Store in cache
            cache[key] = result
            freq[key] = 1
            if min_freq == 0 or min_freq > 1:
                min_freq = 1
            # Evict if necessary
            if len(cache) > maxsize:
                # Find the minimum frequency among keys
                min_f = min(freq.values())
                # Find a key with that frequency to evict
                for evict_key, f in freq.items():
                    if f == min_f:
                        break
                # Remove from cache and freq
                cache.pop(evict_key, None)
                freq.pop(evict_key, None)
                # Update min_freq if needed
                if freq:
                    min_freq = min(freq.values())
                else:
                    min_freq = 0
            return result
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        return wrapper
    return decorator

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    # Attempt to check if the key is present; handle unhashable keys
    try:
        if key in self:
            return self[key]
    except TypeError as e:
        raise TypeError(f"unhashable key: {key}") from e

    # Key is not present; set it to the default value
    try:
        self[key] = default
    except TypeError as e:
        # This usually indicates the key is unhashable
        raise TypeError(f"unhashable key: {key}") from e

    return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        if key in self:
            return self[key]
    except Exception:
        # If key is unhashable, or self is not a mapping, or any other error occurs,
        # fall back to the default value.
        return default
    return default

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except (OSError, UnicodeDecodeError, FileNotFoundError):
            return None

