@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    # Attempt to access the logging module; if unavailable, exit gracefully
    try:
        root = logging.getLogger()
    except NameError:
        # logging module not imported; nothing to reset
        return
    except Exception:
        # Unexpected error accessing logging; exit
        return

    # Reset the root logger configuration
    try:
        # Remove all existing handlers
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        # Reset the log level to the default (WARNING)
        root.setLevel(logging.WARNING)
        # Reconfigure basic logging settings
        logging.basicConfig()
    except Exception as exc:
        # If logging is available, log the failure; otherwise ignore
        try:
            logging.getLogger().error("Failed to reset logging: %s", exc)
        except Exception:
            pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    # Attempt to retrieve the implementation attribute
    impl = getattr(self, "_impl", None)
    if impl is None:
        raise ValueError("Implementation attribute '_impl' is not set.")
    # Determine the name of the implementation
    if isinstance(impl, type):
        name = impl.__name__
    else:
        name = str(impl)
    # Strip known suffixes
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            name = name[: -len(suffix)]
            break
    return name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        # Import lazily to avoid unnecessary overhead and to keep the function self‑contained.
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
        return _directlyProvidedBy(object)
    except Exception:
        # If the object is not a valid target for interface introspection, return an empty declaration.
        from zope.interface.interfaces import IDeclaration
        return IDeclaration()

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    try:
        if all:
            names = dir(self.__class__)
        else:
            names = list(self.__class__.__dict__.keys())
        result = []
        for name in names:
            if name.startswith('_'):
                continue
            try:
                value = getattr(self.__class__, name)
            except Exception:
                continue
            if callable(value):
                continue
            description = ''
            if hasattr(value, "__doc__") and value.__doc__:
                description = value.__doc__.strip()
            result.append((name, description))
        result.sort(key=lambda x: x[0])
        return result
    except Exception as exc:
        raise RuntimeError(f"Error retrieving names and descriptions: {exc}") from exc

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")
    attr_names = set()
    # Determine which classes to inspect
    classes = (self.__class__.__mro__ if all else (self.__class__,))
    for cls in classes:
        # Skip the base 'object' class
        if cls is object:
            continue
        for name, value in cls.__dict__.items():
            # Ignore private/internal names and callables
            if name.startswith("_") or callable(value):
                continue
            attr_names.add(name)
    return sorted(attr_names)

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
    except Exception:
        # If the required function is missing or raises an error, assume optimizations are not required.
        return False
    # Ensure the result is a boolean before negating.
    return not bool(required)

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        try:
            # Reset the context
            self.context = {}

            # Reinitialize bins
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Preserve the current number of bins if they exist
                if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                    bin_count = len(self.bins)
                else:
                    # If bins are not yet defined, create a single bin
                    bin_count = 1
                self.bins = [self.initial_value for _ in range(bin_count)]
            else:
                # Use the factory method to create new bins
                if hasattr(self, "make_bins") and callable(self.make_bins):
                    self.bins = self.make_bins()
                else:
                    raise AttributeError("Histogram has no method to create bins.")
        except Exception as exc:
            # Log the exception or re-raise with context
            raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []
    if header is not None:
        lines.append(header)

    # Determine iterable of points
    points_iter = None
    if hasattr(self, "points"):
        points_attr = getattr(self, "points")
        if callable(points_attr):
            try:
                points_iter = points_attr()
            except Exception as exc:
                raise RuntimeError(f"Failed to obtain points from self.points(): {exc}") from exc
        else:
            points_iter = points_attr
    elif hasattr(self, "__iter__"):
        points_iter = self
    else:
        raise AttributeError("Object has no points to iterate")

    # Iterate over points
    for point in points_iter:
        # Determine coordinate and value
        if isinstance(point, (list, tuple)):
            if len(point) == 2:
                coord, value = point
            else:
                coord = point[0]
                value = point[1:]
        else:
            coord = point
            value = None

        # Convert coordinate to string parts
        if isinstance(coord, (list, tuple)):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Convert value to string parts
        if value is None:
            value_parts = []
        else:
            # Treat strings and bytes as scalars
            if isinstance(value, (str, bytes)):
                value_parts = [str(value)]
            elif isinstance(value, (list, tuple, set)):
                value_parts = [str(v) for v in value]
            else:
                value_parts = [str(value)]

        # Build line
        line_parts = coord_parts + value_parts
        lines.append(separator.join(line_parts))

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the error indices mapping exists
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")

    # Retrieve indices for the given coordinate
    try:
        indices = self._err_indices[coord_name]
    except KeyError:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices")

    # If indices is None, treat as empty
    if indices is None:
        return []

    # Return a copy to avoid accidental mutation
    if isinstance(indices, (list, tuple)):
        return list(indices)
    try:
        return list(indices)
    except TypeError:
        raise TypeError(f"Error indices for coordinate '{coord_name}' must be iterable")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Check if seq itself is a Source sequence
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        pass

    # Check if seq is a single FillRequest
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        pass

    # Ensure seq is iterable (but not a string/bytes)
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    if isinstance(seq, (str, bytes)):
        return False

    any_fill = False
    all_source = True
    for item in seq:
        # Check for FillRequest
        try:
            if isinstance(item, FillRequest):
                any_fill = True
        except NameError:
            pass

        # Check for Source
        try:
            if not isinstance(item, Source):
                all_source = False
        except NameError:
            all_source = False

        # Early exit if we already know the result
        if any_fill and not all_source:
            return True

    # Final decision
    if any_fill and not all_source:
        return True
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'request'))
