        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except Exception:
        return False

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Ensure we have a dictionary
    if not isinstance(labels, dict):
        raise ValidationError(
            messages=[{"labels": "Expected a dictionary of labels"}]
        )

    errors = []

    # Iterate over key-value pairs
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Validate key regex
            try:
                if not LABEL_KEY_REGEX.match(key):
                    errors.append(
                        {
                            key: f"Label key '{key}' does not match the regex "
                            f"'{LABEL_KEY_REGEX.pattern}'"
                        }
                    )
            except Exception:
                # If regex matching fails due to invalid pattern, record generic error
                errors.append(
                    {
                        key: f"Label key '{key}' could not be validated against the regex"
                    }
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            # Validate value regex
            try:
                if not LABEL_VALUE_REGEX.match(value):
                    errors.append(
                        {
                            value: f"Label value '{value}' does not match the regex "
                            f"'{LABEL_VALUE_REGEX.pattern}'"
                        }
                    )
            except Exception:
                errors.append(
                    {
                        value: f"Label value '{value}' could not be validated against the regex"
                    }
                )

    if errors:
        raise ValidationError(messages=errors)

