def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema`` describing the
            expected structure of the list items.
        response (list): partial response from the Kubernetes API.

    This function iterates over the observed fields and initializes their
    values in ``last_applied_manifest`` if they are not yet present.  It
    delegates the update of individual list items to
    :func:`update_last_applied_manifest_dict_from_resp`.

    Returns:
        None. The ``last_applied_manifest`` list is modified in place.
    """
    # Basic type validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Ensure the manifest list is at least as long as the response
    for idx, resp_item in enumerate(response):
        # Expand the manifest list if necessary
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append({})
        # Ensure the current element is a dict (or replace it)
        if not isinstance(last_applied_manifest[idx], dict):
            last_applied_manifest[idx] = {}

        # Determine the schema for this item
        if len(observer_schema) == 1:
            item_schema = observer_schema[0]
        else:
            # Use the schema at the same index if available, otherwise fall back
            # to the last schema entry
            item_schema = observer_schema[idx] if idx < len(observer_schema) else observer_schema[-1]

        # If the response item is a dict, recurse into the dict update
        if isinstance(resp_item, dict):
            try:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], item_schema, resp_item
                )
            except Exception:
                # If the recursive update fails, fall back to a shallow copy
                last_applied_manifest[idx] = resp_item.copy()
        else:
            # For non-dict items, simply assign the value
            last_applied_manifest[idx] = resp_item

    # If the manifest list is longer than the response, truncate the excess
    if len(last_applied_manifest) > len(response):
        del last_applied_manifest[len(response):]

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        # Convert to string path
        path_str = str(path)
        # Check if path exists and is a directory
        try:
            if not os.path.isdir(path_str):
                return False
        except NameError:
            # os module not available
            return False
        # Check for required file .ocfl_version
        try:
            ocfl_version_file = os.path.join(path_str, ".ocfl_version")
            if not os.path.isfile(ocfl_version_file):
                return False
        except NameError:
            return False
        # Additional validation logic can be added here
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        # If a 'status' attribute exists, use it directly
        if hasattr(self, 'status'):
            status = self.status
            return f"{prefix}{status if isinstance(status, str) else str(status)}"

        # If a 'valid' attribute exists, report validity
        if hasattr(self, 'valid'):
            if self.valid:
                return f"{prefix}Valid"
            # Gather errors if present
            errors = getattr(self, 'errors', None) or getattr(self, 'error', None)
            if errors:
                if isinstance(errors, (list, tuple)):
                    errors_str = ', '.join(map(str, errors))
                else:
                    errors_str = str(errors)
                return f"{prefix}Invalid: {errors_str}"
            return f"{prefix}Invalid"

        # Fallback to the object's string representation
        return f"{prefix}{str(self)}"
    except Exception as exc:
        return f"{prefix}Error retrieving status: {exc}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Ensure prefix is a string
        if prefix is None:
            prefix = ''
        if not isinstance(prefix, str):
            prefix = str(prefix)

        # Attempt to retrieve the log from common attribute names
        log = getattr(self, '_log', None)
        if log is None:
            log = getattr(self, 'log', None)

        # If no log is available, return a default message
        if log is None:
            return f"{prefix}No validation log available."

        # If the log is a single string (or bytes), just return it with prefix
        if isinstance(log, (str, bytes)):
            return f"{prefix}{log}"

        # Ensure the log is iterable; if not, treat it as a single entry
        if not hasattr(log, '__iter__'):
            return f"{prefix}{str(log)}"

        # Build the prefixed string representation
        lines = []
        for entry in log:
            # Convert non-string entries to string safely
            if not isinstance(entry, str):
                try:
                    entry = str(entry)
                except Exception:
                    entry = '<unrepresentable entry>'
            lines.append(f"{prefix}{entry}")

        return "\n".join(lines)

    except Exception as exc:
        # Fallback in case of unexpected errors
        return f"{prefix}Error generating status string: {exc}"

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type checks
        if not isinstance(inventory, dict):
            raise TypeError("Inventory must be a dictionary")

        # Determine spec version if requested
        spec_version = self.spec_version
        if extract_spec_version:
            type_value = inventory.get("type")
            # Map known type values to spec versions
            type_to_version = {
                "v1": "1.0",
                "v2": "2.0",
                "legacy": "0.9",
            }
            if isinstance(type_value, str) and type_value in type_to_version:
                spec_version = type_to_version[type_value]
            else:
                # If type is missing or unrecognized, fall back to self.spec_version
                pass

        # Perform simple validation based on spec_version
        # These checks are illustrative; adjust as needed for real spec
        required_keys = ["name", "items"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' in inventory")

        if not isinstance(inventory["name"], str):
            raise TypeError("Inventory 'name' must be a string")

        if not isinstance(inventory["items"], list):
            raise TypeError("Inventory 'items' must be a list")

        # Example spec-specific checks
        if spec_version == "1.0":
            # In spec 1.0, each item must have 'id' and 'quantity'
            for idx, item in enumerate(inventory["items"]):
                if not isinstance(item, dict):
                    raise TypeError(f"Item at index {idx} must be a dict")
                if "id" not in item or "quantity" not in item:
                    raise ValueError(f"Item at index {idx} missing 'id' or 'quantity'")
                if not isinstance(item["quantity"], int) or item["quantity"] < 0:
                    raise ValueError(f"Item at index {idx} has invalid 'quantity'")
        elif spec_version == "2.0":
            # In spec 2.0, items can be dicts or strings (IDs)
            for idx, item in enumerate(inventory["items"]):
                if isinstance(item, dict):
                    if "id" not in item:
                        raise ValueError(f"Item at index {idx} missing 'id'")
                elif isinstance(item, str):
                    # string ID is acceptable
                    pass
                else:
                    raise TypeError(f"Item at index {idx} must be a dict or string")
        else:
            # Unknown spec version: perform minimal checks
            pass

        # If all checks pass, return True
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Validate inputs
        if manifest_files is None:
            raise TypeError("manifest_files cannot be None")
        if digests_used is None:
            raise TypeError("digests_used cannot be None")

        # Extract digests from manifest_files
        if isinstance(manifest_files, dict):
            # Assume values are digests
            manifest_digests = set(manifest_files.values())
        elif isinstance(manifest_files, (list, tuple, set)):
            # Assume the iterable itself contains digests
            manifest_digests = set(manifest_files)
        else:
            raise TypeError(f"Unsupported type for manifest_files: {type(manifest_files).__name__}")

        # Normalize digests_used to a set
        if isinstance(digests_used, (set, frozenset)):
            used_digests = set(digests_used)
        elif isinstance(digests_used, (list, tuple)):
            used_digests = set(digests_used)
        else:
            raise TypeError(f"Unsupported type for digests_used: {type(digests_used).__name__}")

        # Determine missing digests
        missing = manifest_digests - used_digests
        if missing:
            missing_str = ", ".join(sorted(missing))
            raise ValueError(f"Missing digests in manifest that are not used: {missing_str}")

        # All digests present and used
        return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Ensure both objects have an 'inventory' attribute
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError(
            "Both self and prior must have an 'inventory' attribute"
        )

    # Helper to extract a comparable version identifier
    def _get_version(obj):
        inv = getattr(obj, "inventory", None)
        if inv is None:
            raise AttributeError("inventory attribute is None")
        # Prefer a numeric version, otherwise fallback to timestamp
        for attr in ("version", "timestamp", "created_at"):
            if hasattr(inv, attr):
                return getattr(inv, attr)
        # If no suitable attribute, raise
        raise AttributeError(
            f"inventory object {inv!r} lacks 'version', 'timestamp', or 'created_at' attributes"
        )

    try:
        self_version = _get_version(self)
        prior_version = _get_version(prior)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve version information: {exc}") from exc

    # Compare versions; they must be comparable
    try:
        if prior_version >= self_version:
            raise ValueError(
                f"prior version ({prior_version}) must be older than current version ({self_version})"
            )
    except TypeError as exc:
        raise TypeError(
            f"Version attributes are not comparable: {exc}"
        ) from exc

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be provided")

    result = {}
    for logical_path, entries in inventory.items():
        # Normalize entries to a list
        if isinstance(entries, dict):
            entries = [entries]
        elif not isinstance(entries, (list, tuple)):
            # Skip unsupported entry types
            continue

        content_files = set()
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            # Ensure required keys exist
            if 'content_file' not in entry or 'version' not in entry:
                continue
            try:
                # Compare versions; allow numeric or string comparison
                if entry['version'] == version:
                    content_files.add(entry['content_file'])
            except Exception:
                # Skip entries with incomparable version values
                continue

        if content_files:
            result[logical_path] = content_files

    return result

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")
    try:
        manifest_set = set(manifest_files)
    except Exception as exc:
        raise ValueError(f"Manifest files must be an iterable of strings: {exc}") from exc

    # Ensure all manifest entries are strings
    for mf in manifest_set:
        if not isinstance(mf, str):
            raise ValueError(f"Manifest file names must be strings, got {type(mf).__name__}")

    # Validate each entry in the fixity block
    for path, hash_val in fixity.items():
        if not isinstance(path, str):
            raise ValueError(f"Fixity key must be a string, got {type(path).__name__}")
        if not isinstance(hash_val, str):
            raise ValueError(f"Fixity value for '{path}' must be a string, got {type(hash_val).__name__}")
        if path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{path}' not present in manifest")

    # Optionally, you could also check that every manifest file has a fixity entry
    # but the specification only requires that references are valid.

    return True

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Validate input
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")
    if not os.path.exists(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist")
    if not os.path.isdir(folder):
        raise NotADirectoryError(f"'{folder}' is not a directory")

    # Collect all files in the folder (non-recursive)
    try:
        entries = os.listdir(folder)
    except OSError as exc:
        raise OSError(f"Error accessing folder '{folder}': {exc}") from exc

    # Map from XML basename to list of file paths
    groups = {}
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue  # skip subdirectories or non-files
        name, ext = os.path.splitext(entry)
        if ext.lower() == ".xml":
            # Start a new group for this XML file
            groups[name] = [full_path]
        else:
            # Check if this file shares a basename with an existing XML
            if name in groups:
                groups[name].append(full_path)
            else:
                # If no XML counterpart yet, we can still create a group
                # but only if there is an XML file with the same basename later.
                # For simplicity, we ignore files without an XML counterpart.
                pass

    # Optionally, ensure that each group contains at least the XML file
    # If a group has no XML file (unlikely), we can drop it.
    cleaned_groups = {}
    for base, files in groups.items():
        # Verify that at least one file has .xml extension
        has_xml = any(f.lower().endswith(".xml") for f in files)
        if has_xml:
            cleaned_groups[base] = files

    return cleaned_groups

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language code
    if not isinstance(lang, str):
        raise TypeError("lang must be a string")
    if not lang:
        raise ValueError("lang cannot be empty")
    # Validate file path
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if not file_path:
        raise ValueError("file_path cannot be empty")
    # Ensure renditions dictionary exists
    if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
        self.renditions = {}
    # Add or update the rendition
    self.renditions[lang] = file_path

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path to a zip file")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Identify all basenames that have an XML file
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(base)

            # Group files by those basenames
            result = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base in xml_basenames:
                    if base not in result:
                        result[base] = {}
                    try:
                        data = zf.read(info.filename)
                    except Exception as e:
                        # If reading fails, store None or skip
                        data = None
                    result[base][info.filename] = data

            return result

    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        # Generic exception handling to avoid leaking internal errors
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    seen = set()

    def _pretty(obj, level):
        # Avoid infinite recursion on circular references
        if id(obj) in seen:
            return '...'
        seen.add(id(obj))

        prefix = ' ' * level

        # Simple immutable types
        if isinstance(obj, (str, int, float, bool, type(None))):
            if debug:
                return f"{type(obj).__name__}({repr(obj)})"
            return repr(obj)

        # Dictionaries
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                key_repr = repr(k)
                val_repr = _pretty(v, level + 2)
                items.append(f"{prefix}  {key_repr}: {val_repr}")
            return '{\n' + ',\n'.join(items) + f'\n{prefix}}}'

        # Lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            open_sym = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            close_sym = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            items = [f"{prefix}  {_pretty(v, level + 2)}" for v in obj]
            return f"{open_sym}\n" + ',\n'.join(items) + f"\n{prefix}{close_sym}"

        # Objects that provide their own pretty method
        if hasattr(obj, 'pretty') and callable(getattr(obj, 'pretty')):
            try:
                return obj.pretty(level, debug)
            except Exception:
                # Fallback to repr if pretty fails
                pass

        # Fallback for other objects
        if debug:
            return f"{type(obj).__name__}({repr(obj)})"
        return repr(obj)

    return _pretty(self, indent)

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that the hook is hashable (so it can be used as a dict key)
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError("Hook must be hashable") from exc

    def decorator(func):
        if not callable(func):
            raise TypeError("Listener must be callable")

        try:
            # Retrieve or create the registry dictionary
            registry = getattr(self, "_handlers", None)
            if registry is None:
                registry = {}
                setattr(self, "_handlers", registry)

            # Append the function to the list of handlers for this hook
            registry.setdefault(hook, []).append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook}") from exc

        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        # Call the original function
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            # Propagate any exception from the original function
            raise
        # Import sys lazily to avoid unnecessary imports
        sys = __import__('sys')
        # In Python 2, convert unicode to bytestring
        if sys.version_info[0] == 2:
            try:
                unicode_type = unicode
            except NameError:
                # Fallback for environments where unicode is not defined
                unicode_type = str
            if isinstance(result, unicode_type):
                try:
                    return result.encode('utf-8')
                except Exception as e:
                    # Raise a clear error if encoding fails
                    raise ValueError("tzname returned a unicode string that could not be encoded to UTF-8") from e
        # In Python 3 or if no conversion needed, return the result unchanged
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to import the metadata module in a way that works on both
    # Python 3.8+ (importlib.metadata) and older versions (importlib_metadata).
    try:
        import importlib.metadata as importlib_metadata
    except Exception:
        try:
            import importlib_metadata
        except Exception:
            # If we cannot import either, return a default version string.
            return "0.0.0"

    # Determine the package name to query.  Use __package__ if available,
    # otherwise fall back to __name__.  If that still doesn't look like a
    # distribution name (e.g., "__main__"), we will fall back to the
    # default value.
    pkg_name = __package__ or __name__
    if not pkg_name or pkg_name in ("__main__", "__init__"):
        return "0.0.0"

    # Try to get the version using importlib.metadata.
    try:
        return importlib_metadata.version(pkg_name)
    except Exception:
        # If that fails, try pkg_resources as a fallback.
        try:
            import pkg_resources
            return pkg_resources.get_distribution(pkg_name).version
        except Exception:
            # If all attempts fail, return the default version string.
            return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if pieces is None:
        raise TypeError("pieces cannot be None")
    if style is None:
        raise TypeError("style cannot be None")

    # Ensure pieces is an iterable of strings or integers (but not a string itself)
    if isinstance(pieces, (str, bytes)):
        raise TypeError("pieces must be an iterable, not a string")
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of strings or integers")

    # Convert each piece to a string, raising if conversion fails
    try:
        str_pieces = [str(p) for p in pieces]
    except Exception as exc:
        raise TypeError("all elements of pieces must be convertible to string") from exc

    # Define rendering logic for supported styles
    if style == "semver":
        # Simple dot-separated version
        return ".".join(str_pieces)

    if style == "pep440":
        # PEP 440 allows numeric parts separated by dots, followed by a pre/post/dev suffix
        numeric_parts = []
        suffix = ""
        for part in str_pieces:
            if part.isdigit():
                numeric_parts.append(part)
            else:
                suffix += part
        return ".".join(numeric_parts) + suffix

    if style == "full":
        # Return the tuple representation
        return str(tuple(str_pieces))

    if style == "short":
        # Return the first two components joined by dots
        return ".".join(str_pieces[:2])

    if style == "comma":
        # Join components with commas
        return ",".join(str_pieces)

    if style == "space":
        # Join components with spaces
        return " ".join(str_pieces)

    # If the style is not recognized, raise an informative error
    raise ValueError(f"Unsupported style '{style}'. Supported styles are: "
                     "semver, pep440, full, short, comma, space.")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise TypeError("pieces cannot be None")
    try:
        return '.' if '+' in pieces else '+'
    except TypeError:
        raise TypeError("pieces must be an iterable containing '+' or not") from None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    # Build the command list
    if isinstance(commands, str):
        # Split the command string into a list
        cmd_list = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    full_cmd = cmd_list + list(args)

    # Prepare environment
    env_dict = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict")
        env_dict.update(env)

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")
        if cwd:
            print(f"Working directory: {cwd}")

    # Set stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            check=True
        )
        return result.stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except subprocess.CalledProcessError as e:
        # If hide_stderr is False, include stderr in the message
        err_msg = e.stderr if e.stderr else ""
        raise RuntimeError(f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}. {err_msg}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running command '{' '.join(full_cmd)}': {e}") from e

