def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError(f"validate_objects must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"check_digests must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"show_warnings must be a bool, got {type(show_warnings).__name__}")

    # Ensure storage_root attribute exists and is a directory
    if not hasattr(self, "storage_root"):
        raise AttributeError("The object does not have a 'storage_root' attribute.")
    root = getattr(self, "storage_root")
    if not isinstance(root, str):
        raise TypeError(f"storage_root must be a string path, got {type(root).__name__}")
    if not os.path.isdir(root):
        raise ValueError(f"storage_root '{root}' is not a valid directory.")

    num_objects = 0
    good_objects = 0

    # Helper to compute SHA256 digest of a file
    def _compute_digest(file_path):
        try:
            sha = hashlib.sha256()
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha.update(chunk)
            return sha.hexdigest()
        except Exception:
            return None

    for dirpath, dirnames, filenames in os.walk(root):
        # Count directories as objects (optional)
        for dirname in dirnames:
            num_objects += 1
            # Directories are considered valid by default
            good_objects += 1

        for filename in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            is_valid = True

            # Validate object existence and readability
            if validate_objects:
                try:
                    with open(file_path, "rb"):
                        pass
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Cannot read file '{file_path}': {e}")

            # Check digest if requested
            if is_valid and check_digests:
                # Look for a corresponding .sha256 file
                digest_file = file_path + ".sha256"
                if os.path.isfile(digest_file):
                    try:
                        with open(digest_file, "r") as df:
                            expected = df.read().strip()
                    except Exception as e:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: Cannot read digest file '{digest_file}': {e}")
                    else:
                        actual = _compute_digest(file_path)
                        if actual is None:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Failed to compute digest for '{file_path}'.")
                        elif actual.lower() != expected.lower():
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Digest mismatch for '{file_path}'. Expected {expected}, got {actual}.")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return {}

    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("The object must have a 'root_inventory' dict attribute")

    results = {}
    for vdir in version_dirs:
        # Default result entry for this version
        entry = {"missing_inventory": False, "digest_mismatches": []}

        # Construct the expected inventory file path
        inv_path = os.path.join(vdir, "inventory.json")

        # Attempt to load the inventory
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except FileNotFoundError:
            entry["missing_inventory"] = True
            results[vdir] = entry
            continue
        except (OSError, json.JSONDecodeError):
            # Any other I/O or parsing error is treated as a missing/invalid inventory
            entry["missing_inventory"] = True
            results[vdir] = entry
            continue

        # Inventory should be a mapping of file paths to digests
        if not isinstance(inv, dict):
            entry["missing_inventory"] = True
            results[vdir] = entry
            continue

        # Compare each digest against the root inventory
        for path, digest in inv.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is None:
                # File not present in root inventory; skip or record as needed
                continue
            if digest != root_digest:
                entry["digest_mismatches"].append(path)

        results[vdir] = entry

    return results

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except OSError as e:
                return f"Cannot list directory '{path}': {e}"
            # Check for Namaste file
            if "0=*" not in entries:
                return f"No Namaste file '0=*' found in directory: {path}"
            # Determine if root or object
            objects_dir = os.path.join(path, "objects")
            if "objects" in entries and os.path.isdir(objects_dir):
                return 'root'
            else:
                return 'object'
        return f"Path is neither file nor directory: {path}"
    except Exception as e:
        return f"Error while determining path type: {e}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two nodes
    def _merge_nodes(a, b):
        # If both are MappingNode, merge recursively
        try:
            from ruamel.yaml.nodes import MappingNode
        except Exception:
            # If ruamel is not available, just return b
            return b
        if isinstance(a, MappingNode) and isinstance(b, MappingNode):
            # Merge the value lists
            merged_value = deep_merge_nodes(a.value + b.value)
            return MappingNode(tag=a.tag, value=merged_value)
        # For any other case, last wins
        return b

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')
    result = []
    key_index = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('Each item must be a tuple of (ScalarNode, Node)')
        key_node, val_node = item
        # Use the key's value as the dictionary key
        try:
            key_val = key_node.value
        except AttributeError:
            raise ValueError('Key node must have a value attribute')
        if key_val in key_index:
            idx = key_index[key_val]
            existing_key_node, existing_val_node = result[idx]
            merged_val = _merge_nodes(existing_val_node, val_node)
            result[idx] = (existing_key_node, merged_val)
        else:
            result.append((key_node, val_node))
            key_index[key_val] = len(result) - 1
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # argparse.ArgumentParser instances expose a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # Each action may have an option_strings attribute (list of flag strings)
            option_strings = getattr(action, "option_strings", [])
            if option_strings:
                flags.extend(option_strings)
        return " ".join(flags)
    except Exception as exc:
        # If any unexpected error occurs, raise a TypeError with context
        raise TypeError("Failed to extract flags from parser") from exc

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a MappingNode (duck‑typing)
    def _is_mapping_node(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and isinstance(node.value, list)

    # Recursive merge of two node values
    def _merge_values(v1, v2):
        if _is_mapping_node(v1) and _is_mapping_node(v2):
            # Merge mapping nodes recursively
            merged_pairs = {}
            # First, add all pairs from v1
            for k_node, val_node in v1.value:
                merged_pairs[k_node.value] = (k_node, val_node)
            # Then merge/overwrite with pairs from v2
            for k_node, val_node in v2.value:
                k = k_node.value
                if k in merged_pairs:
                    _, existing_val = merged_pairs[k]
                    merged_pairs[k] = (k_node, _merge_values(existing_val, val_node))
                else:
                    merged_pairs[k] = (k_node, val_node)
            # Build the merged list preserving order: first v1 order, then v2 order for new keys
            merged_list = []
            seen_keys = set()
            for k_node, val_node in v1.value:
                k = k_node.value
                if k not in seen_keys:
                    merged_list.append(merged_pairs[k])
                    seen_keys.add(k)
            for k_node, val_node in v2.value:
                k = k_node.value
                if k not in seen_keys:
                    merged_list.append(merged_pairs[k])
                    seen_keys.add(k)
            # Construct a new MappingNode of the same type as v1
            return type(v1)(tag=v1.tag, value=merged_list)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    try:
        actions = parser._actions
    except AttributeError:
        return ""
    try:
        for action in actions:
            try:
                option_strings = action.option_strings
            except AttributeError:
                continue
            if not option_strings:
                continue
            try:
                for opt in option_strings:
                    if isinstance(opt, str):
                        flags.append(opt)
            except TypeError:
                continue
    except TypeError:
        return ""
    return " ".join(flags)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator that yields slices of the response list
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Wrap any unexpected exception in a RuntimeError for clarity
        raise RuntimeError("An error occurred while paging the response") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("The argument must be an iterable of dictionaries") from None

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Item at index {idx} is not a dictionary")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' in dictionary at index {idx} is not numeric")
            result[key] = result.get(key, 0) + value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        return val.strip().lower() == "none"
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate that the object behaves like an ArgumentParser by checking for the
    # expected internal attribute `_actions`.  We avoid importing argparse to keep
    # the function self-contained.
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Each action should expose an `option_strings` attribute containing
        # the flag names (e.g., ['-h', '--help']).  Positional arguments
        # have an empty list, which we simply ignore.
        try:
            option_strings = action.option_strings
        except AttributeError:
            continue
        if option_strings:
            flags.extend(option_strings)

    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate input types
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("alphabet must contain strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")
    if number < 0:
        raise ValueError("number must be non-negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if requested
    if padding is not None and padding > len(digits):
        digits = [alphabet[0]] * (padding - len(digits)) + digits

    return ''.join(digits)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve subclasses of {cls}") from exc
    for sub in direct_subs:
        result.add(sub)
        # Recursively gather subclasses of the subclass
        try:
            result.update(subclasses(sub))
        except Exception as exc:
            # If a subclass causes an error, skip it but continue processing others
            continue
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain unique characters")
    base = len(alphabet)
    result = 0
    for ch in string:
        try:
            digit = alphabet.index(ch)
        except ValueError:
            raise ValueError(f"Character '{ch}' not in alphabet") from None
        result = result * base + digit
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove surrounding single or double quotes if present
    match = re.match(r"^(['\"])(.*)\1$", name)
    if match:
        return match.group(2)
    return name

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex

    if not isinstance(s, str):
        raise TypeError(f"Expected string input, got {type(s).__name__}")

    # Determine platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 'this', 0 (Windows), or 1 (POSIX)")

    # Empty string -> empty list
    if not s.strip():
        return []

    if platform == 1:  # POSIX
        # Regex to capture quoted or unquoted tokens
        token_re = re.compile(
            r'''(?:(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^ \t\n\r\f\v]+)))'''
        )
        args = []
        pos = 0
        for m in token_re.finditer(s):
            start, end = m.span()
            # Check for any non-whitespace between previous match and this match
            if start > pos and not s[pos:start].isspace():
                raise ValueError(f"Invalid syntax near: {s[pos:start]}")
            pos = end
            if m.group(1) is not None:
                token = m.group(1)
            elif m.group(2) is not None:
                token = m.group(2)
            else:
                token = m.group(3)
            # Unescape backslashes
            token = re.sub(r'\\(.)', r'\1', token)
            args.append(token)
        # Check trailing garbage
        if pos < len(s) and not s[pos:].isspace():
            raise ValueError(f"Invalid syntax near: {s[pos:]}")
        return args

    else:  # Windows
        # Use shlex with posix=False for Windows quoting rules
        try:
            return shlex.split(s, posix=False)
        except ValueError as e:
            raise ValueError(f"Windows split error: {e}") from None

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Dynamically import required modules
    os = __import__("os")
    pathlib = __import__("pathlib")
    uuid = __import__("uuid")
    subprocess = __import__("subprocess")

    # Resolve tmp_path to a string path
    tmp_dir = str(tmp_path)

    # Ensure the temporary directory exists
    try:
        os.makedirs(tmp_dir, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create temporary directory '{tmp_dir}': {e}")

    # Create a unique extraction directory inside tmp_dir
    extraction_dir = os.path.join(tmp_dir, f"extract_{uuid.uuid4().hex}")
    try:
        os.makedirs(extraction_dir, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create extraction directory '{extraction_dir}': {e}")

    # Determine archive type based on file extension
    archive_path_str = str(archive_path)
    suffix = pathlib.Path(archive_path_str).suffix.lower()
    # Handle compound suffixes like .tar.gz
    if suffix == ".gz" and archive_path_str.lower().endswith(".tar.gz"):
        suffix = ".tar.gz"
    elif suffix == ".bz2" and archive_path_str.lower().endswith(".tar.bz2"):
        suffix = ".tar.bz2"
    elif suffix == ".tgz":
        suffix = ".tgz"

    # Build extraction command
    if suffix == ".zip":
        cmd = ["unzip", "-q", archive_path_str, "-d", extraction_dir]
    elif suffix in {".tar", ".tar.gz", ".tgz", ".tar.bz2"}:
        cmd = ["tar", "-xf", archive_path_str, "-C", extraction_dir]
    else:
        raise ValueError(f"Unsupported archive format for file '{archive_path_str}'")

    # Execute extraction
    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except FileNotFoundError as e:
        raise RuntimeError(f"Extraction tool not found: {e}")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Extraction failed: {e.stderr.decode().strip()}")

    # Determine the repository root directory
    try:
        entries = os.listdir(extraction_dir)
    except Exception as e:
        raise RuntimeError(f"Failed to list extraction directory '{extraction_dir}': {e}")

    repo_root = extraction_dir
    if len(entries) == 1:
        single_entry = os.path.join(extraction_dir, entries[0])
        if os.path.isdir(single_entry):
            repo_root = single_entry

    # Return file URL
    return f"file://{repo_root}"

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host:
        return False

    # Direct string checks for common localhost identifiers
    host_lower = host.lower()
    if host_lower in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all possible addresses
        addr_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, UnicodeError):
        # If resolution fails, we cannot determine if it's local
        return False

    for family, _, _, _, sockaddr in addr_info:
        # sockaddr is a tuple; for IPv4 it's (address, port), for IPv6 it's (address, port, flowinfo, scopeid)
        ip = sockaddr[0]
        if ip == "127.0.0.1" or ip == "::1":
            return True

    # As a fallback, compare against the local machine's IP addresses
    try:
        local_ips = socket.gethostbyname_ex(socket.gethostname())[2]
        if host in local_ips:
            return True
    except Exception:
        pass

    return False

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    try:
        if script is None:
            return ""
        # Ensure script is a string
        if not isinstance(script, str):
            script = str(script)
        # Ensure separator is a string
        if not isinstance(seperator, str):
            seperator = str(seperator)
        # Split into lines, strip whitespace, filter out empty lines
        lines = [line.strip() for line in script.splitlines() if line.strip()]
        # Join with the separator
        return seperator.join(lines)
    except Exception as e:
        # In case of unexpected errors, return an empty string or re-raise
        return ""

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name and optional default from the matcher
    name = None
    default = None

    # Try to treat matcher as a regex match object
    if hasattr(matcher, "group"):
        try:
            name = matcher.group(1)
        except Exception:
            raise ValueError("Matcher must provide a group(1) for the variable name")
        try:
            default = matcher.group(2)
        except Exception:
            # group(2) may not exist; default remains None
            pass
    # If not a match object, try to treat it as a tuple/list
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) < 1:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]
    else:
        raise ValueError("Matcher must be a regex match object or a tuple/list with name and optional default")

    if name is None:
        raise ValueError("Variable name could not be determined from matcher")

    # Retrieve the environment variable
    value = os.environ.get(name)
    if value is not None:
        return value

    # If not set, use default if provided
    if default is not None:
        return default

    # No value and no default: raise an error
    raise KeyError(f"Environment variable '{name}' not set and no default provided")

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        return False

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    if x is None:
        raise ValueError("Input x must not be None.")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be a number or array-like of numbers.") from e
    if arr.size == 0:
        raise ValueError("Input x must not be empty.")
    try:
        result = np.exp(-((arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise ValueError("Error computing Gaussian.") from e
    return result if isinstance(x, (list, tuple, np.ndarray)) else result.item()

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ValueError(f"Could not encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the registry of handlers; use an empty dict if not defined
        handlers = getattr(cls, "_protocol_handlers", {})
        if protocol_version is None:
            # Return a shallow copy to prevent accidental mutation
            return dict(handlers)

        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )

        # Return a dict containing the requested handler if it exists
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable of strings
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}")
    raw_list = []
    for idx, v in enumerate(iterator):
        if not isinstance(v, str):
            raise ValueError(f"Element at index {idx} is not a string: {type(v).__name__}")
        raw_list.append(v)

    # Attempt to create an instance of the class
    try:
        instance = cls()
    except Exception as e:
        raise RuntimeError(f"Failed to instantiate {cls.__name__}: {e}") from e

    # Store the raw values on the instance for later use
    setattr(instance, "_raw_values", raw_list)
    return instance

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure required attributes exist
    required_attrs = ('cache', 'freq', 'freq_map', 'min_freq')
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"LFUCache instance missing required attribute '{attr}'")
    # If cache is empty, raise KeyError
    if not self.cache:
        raise KeyError("Cache is empty")
    # Determine the current minimum frequency
    freq = self.min_freq
    # Get the container of keys for this frequency
    keys_container = self.freq_map.get(freq)
    if not keys_container:
        # If the container is missing, find the next minimum frequency
        if not self.freq_map:
            raise KeyError("Cache is empty")
        freq = min(self.freq_map.keys())
        keys_container = self.freq_map[freq]
    # Pop a key from the container
    try:
        if isinstance(keys_container, set):
            key = keys_container.pop()
        else:
            # Assume OrderedDict or similar supporting popitem(last=False)
            key, _ = keys_container.popitem(last=False)
    except Exception as exc:
        raise KeyError("Failed to pop an item from the frequency container") from exc
    # If the container is now empty, remove it and update min_freq
    if not keys_container:
        del self.freq_map[freq]
        if self.freq_map:
            self.min_freq = min(self.freq_map.keys())
        else:
            self.min_freq = 0
    # Remove the key from the main cache and frequency mapping
    value = self.cache.pop(key, None)
    self.freq.pop(key, None)
    return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    # Ensure the object behaves like a mapping
    if not hasattr(self, "items") or not callable(getattr(self, "items")):
        raise TypeError(f"{self.__class__.__name__} object has no 'items' method")
    try:
        items = list(self.items())
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve items from {self}") from exc
    if not items:
        raise KeyError("popitem(): dictionary is empty")
    # Choose a random item
    import random
    key, value = random.choice(items)
    # Remove the chosen key
    try:
        del self[key]
    except Exception as exc:
        raise RuntimeError(f"Failed to delete key {key!r} from {self}") from exc
    return key, value

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches an IN clause like: IN (value1, value2, ...)
        # Captures the comma‑separated list inside the parentheses.
        return re.compile(r'\bIN\s*\(\s*([^)]*?)\s*\)', re.IGNORECASE)
    except re.error as exc:
        raise ValueError("Failed to compile IN regex") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Validate input
    if request is None:
        raise TypeError("request cannot be None")

    # Helper to get attribute or dict key
    def _get_value(obj, key):
        if isinstance(obj, dict):
            return obj.get(key)
        return getattr(obj, key, None)

    # Check for public message
    try:
        public_val = _get_value(request, "public")
        if public_val:
            return "public"
    except Exception:
        pass

    # Check for private message
    try:
        private_val = _get_value(request, "private")
        if private_val:
            return "private"
    except Exception:
        pass

    # Check for legacy payload
    try:
        legacy_val = _get_value(request, "legacy")
        if legacy_val:
            return "legacy"
    except Exception:
        pass

    # If none matched, return None
    return None

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime-like object and returns a string
    in ISO‑8601 format without microseconds.  Naive datetimes are
    treated as UTC.  Time‑zone aware datetimes are formatted with
    their offset.  Invalid inputs raise a ValueError or TypeError.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    # Basic check for datetime-like object
    if not hasattr(dt, "strftime"):
        raise TypeError("dt must be a datetime object")
    try:
        from datetime import timezone
    except Exception:
        timezone = None
    # Ensure the datetime is timezone aware; assume UTC if not
    tzinfo = getattr(dt, "tzinfo", None)
    if tzinfo is None:
        try:
            dt = dt.replace(tzinfo=timezone.utc)
        except Exception:
            # Fallback: treat as naive UTC
            return dt.replace(microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ")
    # Format without microseconds
    dt = dt.replace(microsecond=0)
    if timezone and dt.tzinfo == timezone.utc:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    # For other time zones, use ISO 8601 with offset
    return dt.isoformat()

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be callable or None")

    # Regex to find code blocks delimited by triple backticks
    code_block_pattern = re.compile(r'```.*?```', re.DOTALL)
    # Regex to find tags: words starting with @ followed by word characters
    tag_pattern = re.compile(r'@(\w+)')

    tags: Set[str] = set()
    result_parts = []
    last_end = 0

    for match in code_block_pattern.finditer(text):
        start, end = match.span()
        # Process the text before the code block
        segment = text[last_end:start]
        if replacer:
            # Replace tags in this segment
            def repl_func(m):
                tag_word = m.group(1)
                tags.add(tag_word)
                try:
                    return replacer(tag_word)
                except Exception:
                    # If replacer fails, keep original tag
                    return m.group(0)
            segment = tag_pattern.sub(repl_func, segment)
        else:
            # Just collect tags
            for m in tag_pattern.finditer(segment):
                tags.add(m.group(1))
        result_parts.append(segment)
        # Append the code block unchanged
        result_parts.append(text[start:end])
        last_end = end

    # Process any remaining text after the last code block
    segment = text[last_end:]
    if replacer:
        def repl_func(m):
            tag_word = m.group(1)
            tags.add(tag_word)
            try:
                return replacer(tag_word)
            except Exception:
                return m.group(0)
        segment = tag_pattern.sub(repl_func, segment)
    else:
        for m in tag_pattern.finditer(segment):
            tags.add(m.group(1))
    result_parts.append(segment)

    new_text = "".join(result_parts)
    return tags, new_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if text is None:
        return ""
    if not isinstance(text, str):
        raise TypeError("process_text_links expects a string input")

    # Regex to find http/https URLs
    url_pattern = re.compile(
        r'(?P<url>https?://[^\s<]+)', re.IGNORECASE
    )

    def replace(match):
        url = match.group('url')
        # Preserve trailing punctuation (.,!?;:)
        trailing = ''
        while url and url[-1] in '.,!?;:':
            trailing = url[-1] + trailing
            url = url[:-1]
        # Build the anchor tag
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>{trailing}'

    try:
        return url_pattern.sub(replace, text)
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        import re
        pattern = re.compile(r'^[a-z0-9]+(?:[-_][a-z0-9]+)*$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("Provided node is not an XML element or iterable") from exc

    result = {}
    for child in children:
        tag = getattr(child, "tag", None)
        if tag is None:
            continue  # skip elements without a tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input types
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Basic URL validation
    try:
        from urllib.parse import urlparse, urljoin
    except Exception as exc:
        raise RuntimeError("Failed to import urllib.parse") from exc

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("url must include a valid http or https scheme")
    if not parsed.netloc:
        raise ValueError("url must include a network location (e.g., example.com)")

    # Determine the NodeInfo document path
    if not document_path:
        document_path = "/nodeinfo/2.0"
    else:
        # Ensure it starts with a slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path

    # Construct the full href
    # Ensure base ends with a slash for correct urljoin behavior
    base = url.rstrip("/") + "/"
    href = urljoin(base, document_path.lstrip("/"))

    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href,
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must decode to a dictionary")
        return data
    except Exception:
        pass  # fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger as JSON or XRD: {e}")

    # Helper to strip namespace
    def _strip_ns(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    # Find subject
    subject_elem = None
    for elem in root.iter():
        if _strip_ns(elem.tag) == 'Subject':
            subject_elem = elem
            break
    subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None

    # Find aliases
    aliases = []
    for elem in root.iter():
        if _strip_ns(elem.tag) == 'Alias' and elem.text:
            aliases.append(elem.text.strip())

    # Find links
    links = []
    for elem in root.iter():
        if _strip_ns(elem.tag) == 'Link':
            link_attrs = {k: v for k, v in elem.attrib.items()}
            # If the link element contains text, include it as 'text' key
            if elem.text and elem.text.strip():
                link_attrs['text'] = elem.text.strip()
            links.append(link_attrs)

    result = {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }
    return result

