def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        if not isinstance(url, str):
            raise ValueError("url must be a string")
        if method is None:
            method = "post"
        method = method.lower()
        import requests
        # Pass all additional arguments to the request call
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        One or more directory paths to search for files.
    spec_option : str or None
        Optional filter for file names. If it starts with '*', it is treated
        as a glob pattern. If it starts with '.', it is treated as a file
        extension. Otherwise, it is treated as a literal suffix.

    Returns
    -------
    list[str]
        A list of full file paths that match the given specification.
    """
    import os
    import fnmatch

    # Normalise settings_dirs to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    matched_files = []

    for directory in dirs:
        if not isinstance(directory, str):
            # Skip non-string entries
            continue
        try:
            entries = os.listdir(directory)
        except OSError:
            # Skip directories that cannot be accessed
            continue

        for entry in entries:
            full_path = os.path.join(directory, entry)
            if not os.path.isfile(full_path):
                continue

            # Apply spec_option filter
            if spec_option is None:
                matched_files.append(full_path)
                continue

            if not isinstance(spec_option, str):
                # Invalid spec_option type; skip filtering
                matched_files.append(full_path)
                continue

            if spec_option.startswith("*"):
                # Glob pattern
                if fnmatch.fnmatch(entry, spec_option):
                    matched_files.append(full_path)
            elif spec_option.startswith("."):
                # Extension filter
                if entry.lower().endswith(spec_option.lower()):
                    matched_files.append(full_path)
            else:
                # Literal suffix
                if entry.lower().endswith(spec_option.lower()):
                    matched_files.append(full_path)

    # Return sorted list for consistency
    return sorted(matched_files)

