@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have something to validate
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # If the content is a string or bytes, attempt to parse it as YAML
        if isinstance(spec_content, (bytes, bytearray)):
            try:
                spec_content = spec_content.decode("utf-8")
            except Exception as exc:
                raise IRValidatorException(f"Unable to decode spec content: {exc}") from exc

        if isinstance(spec_content, str):
            try:
                import yaml
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Invalid YAML content: {exc}") from exc
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(f"Unsupported spec content type: {type(spec_content).__name__}")

        if not isinstance(spec_dict, dict):
            raise IRValidatorException("Spec content must resolve to a dictionary")

        # Define the mandatory fields that must be present in the spec
        required_fields = ["name", "version", "description"]

        missing = [field for field in required_fields if field not in spec_dict or spec_dict[field] in (None, "", [])]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields in spec: {', '.join(missing)}")

        return spec_dict

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from e
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {yaml_file}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a top-level mapping")

        # Assume the class defines a list of required keys
        required_keys = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [k for k in required_keys if k not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        # Retrieve the spec; it should be a mapping of argument names to spec dicts
        spec = getattr(self, "spec", None)
        if not isinstance(spec, dict):
            raise TypeError("`spec` attribute must be a dictionary")

        # Optional fallback defaults that may be defined elsewhere on the instance
        fallback_defaults = getattr(self, "defaults", {})

        resolved = {}
        for name, definition in spec.items():
            # If the definition is a mapping, look for a 'default' key
            if isinstance(definition, dict):
                if "default" in definition:
                    resolved[name] = definition["default"]
                else:
                    # No explicit default in spec; try the fallback defaults
                    resolved[name] = fallback_defaults.get(name, None)
            else:
                # If the spec entry itself is a value, treat it as the default
                resolved[name] = definition

        return resolved
    except Exception:
        # In case of any unexpected error, return an empty mapping
        return {}

