def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    try:
        options_dict = getattr(self, "parser_options", {})
    except Exception as exc:
        raise RuntimeError("Failed to access parser options") from exc
    if not isinstance(options_dict, dict):
        raise RuntimeError("parser_options attribute is not a dict")
    if command_name not in options_dict:
        raise ValueError(f"Unknown command name: {command_name!r}")
    options = options_dict[command_name]
    if not isinstance(options, list):
        try:
            options = list(options)
        except Exception as exc:
            raise RuntimeError("Command options cannot be converted to list") from exc
    return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    try:
        # Retrieve the command object from the registry
        command = self.commands.get(command_name)
        if command is None:
            return None

        # The command may expose its options via an 'options' attribute or dict
        options = getattr(command, "options", None)
        if options is None:
            # If the command itself is a dict, look for an 'options' key
            if isinstance(command, dict):
                options = command.get("options")
            else:
                return None

        # Return the option specification if it exists
        if isinstance(options, dict):
            return options.get(argument_name)
        # If options is not a dict, we cannot retrieve a spec
        return None

    except AttributeError as exc:
        # The object does not have the expected structure
        raise RuntimeError("The object does not have a 'commands' attribute or commands are not properly structured") from exc
    except Exception as exc:
        # Catch-all for unexpected runtime issues
        raise RuntimeError(f"An unexpected error occurred while retrieving option spec: {exc}") from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if args is None:
            return []

        # Determine the collection of argument names
        if isinstance(args, dict):
            keys = args.keys()
        else:
            # Treat a string as a single argument name
            if isinstance(args, str):
                keys = [args]
            else:
                try:
                    iter(args)
                    keys = args
                except TypeError:
                    raise TypeError("args must be an iterable or dict")

        # Determine the set of silent argument names
        silent_set = set()
        if hasattr(self, "silent_args"):
            try:
                silent_set = set(self.silent_args)
            except Exception:
                silent_set = set()
        else:
            # Default silent arguments if none are defined
            silent_set = {"verbose", "debug", "quiet", "silent"}

        # Filter and return the silent argument names
        result = [str(k) for k in keys if str(k) in silent_set]
        return result
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve required arguments list/iterable from the instance
    required = getattr(self, "required_args", None)
    if required is None:
        # No required arguments defined; nothing to validate
        return True
    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError(f"required_args must be an iterable, got {type(required).__name__}")
    # Find any missing required keys
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Validate inputs
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option specifications")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    required = []

    # Prepare a safe evaluation context
    eval_context = {"command_name": command_name}
    eval_context.update(args)

    for opt in options_spec:
        # Extract option name and required_when condition
        if isinstance(opt, dict):
            name = opt.get("name")
            required_when = opt.get("required_when")
        else:
            name = getattr(opt, "name", None)
            required_when = getattr(opt, "required_when", None)

        if not name or required_when is None:
            continue

        try:
            # If required_when is a callable, call it with args
            if callable(required_when):
                if required_when(args):
                    required.append(name)
            else:
                # Treat required_when as a string expression
                # Evaluate in the context of args and command_name
                if eval(required_when, {}, eval_context):
                    required.append(name)
        except Exception:
            # If evaluation fails, skip this option
            continue

    return required

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: True if all arguments are within bounds, False otherwise.
    """
    try:
        # Retrieve min and max bounds from the instance
        min_val = getattr(self, "min", None)
        max_val = getattr(self, "max", None)
        if min_val is None or max_val is None:
            raise AttributeError("Instance must have 'min' and 'max' attributes defined.")

        # Determine the iterable of values to check
        if isinstance(args, dict):
            values = args.values()
        else:
            values = args

        for val in values:
            if not isinstance(val, (int, float)):
                raise TypeError(f"Argument value {val!r} is not numeric.")
            if val < min_val or val > max_val:
                return False
        return True
    except Exception as exc:
        # Wrap any exception in a ValueError to signal validation failure
        raise ValueError(f"Invalid arguments: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation of inputs
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")
        if 'type' not in spec_option:
            raise ValueError("spec_option must contain a 'type' key")

        # Define a lightweight complex type holder
        class ComplexType:
            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                self.spec_option = spec_option

            def __repr__(self):
                return (f"<ComplexType {self.type_name} for "
                        f"{self.subcommand}:{self.option_name}>")

            def parse(self, value):
                """
                Parse a raw string value into the complex type using the
                callable provided in spec_option['type'].
                """
                try:
                    return self.spec_option['type'](value)
                except Exception as exc:
                    raise ValueError(
                        f"Failed to parse value '{value}' for option "
                        f"'{self.option_name}': {exc}"
                    ) from exc

        return ComplexType(subcommand, type_name, option_name, spec_option)

    except Exception as exc:
        raise RuntimeError(
            f"Error creating complex argument type '{type_name}' "
            f"for subcommand '{subcommand}': {exc}"
        ) from exc

