def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess

    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            cmd.append(verbose)

    # Extra vars
    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
        except (TypeError, ValueError) as e:
            raise ValueError(f"Invalid extra_vars: {e}") from e
        cmd.extend(["--extra-vars", extra_json])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            flag = f"--{key.replace('_', '-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([flag, str(v)])
            else:
                cmd.extend([flag, str(value)])

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}") from e

    # Log output if plugin provides logging
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(result.stdout)
        if result.stderr:
            ir_plugin.log(result.stderr, level="error")

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Basic validation
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")
        if parser_name is None:
            parser_name = ""

        # Define type expectations for known parsers
        type_map = {
            "virsh": {
                "timeout": int,
                "debug": bool,
                "options": list,
            },
            "ospd": {
                "port": int,
                "verbose": bool,
                "hosts": list,
            },
            "main": {
                "count": int,
                "verbose": bool,
            },
        }

        parser_map = type_map.get(parser_name.lower(), {})

        for key, value in list(values_dict.items()):
            # Determine target type
            target_type = parser_map.get(key)

            # Helper to convert string booleans
            def _str_to_bool(v):
                if isinstance(v, str):
                    if v.lower() in ("true", "1", "yes", "y"):
                        return True
                    if v.lower() in ("false", "0", "no", "n"):
                        return False
                return None

            # Generic conversion if no explicit type
            if target_type is None:
                if isinstance(value, str):
                    # None literal
                    if value.lower() == "none":
                        values_dict[key] = None
                        continue
                    # Boolean
                    bool_val = _str_to_bool(value)
                    if bool_val is not None:
                        values_dict[key] = bool_val
                        continue
                    # Integer
                    if value.isdigit():
                        try:
                            values_dict[key] = int(value)
                            continue
                        except Exception:
                            pass
                    # Float
                    try:
                        float_val = float(value)
                        values_dict[key] = float_val
                        continue
                    except Exception:
                        pass
                    # List (comma separated)
                    if "," in value:
                        values_dict[key] = [v.strip() for v in value.split(",") if v.strip()]
                        continue
                # If value is already a non-string type, leave it
                continue

            # Explicit type conversion
            try:
                if target_type is bool:
                    bool_val = _str_to_bool(value)
                    if bool_val is not None:
                        values_dict[key] = bool_val
                    else:
                        values_dict[key] = bool(value)
                elif target_type is int:
                    values_dict[key] = int(value)
                elif target_type is float:
                    values_dict[key] = float(value)
                elif target_type is list:
                    if isinstance(value, str):
                        values_dict[key] = [v.strip() for v in value.split(",") if v.strip()]
                    else:
                        values_dict[key] = list(value)
                else:
                    values_dict[key] = target_type(value)
            except Exception:
                # If conversion fails, keep original value
                pass
        # No explicit return; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Validate plugin_dir
    if plugin_dir is None:
        raise TypeError("plugin_dir must not be None")
    if not isinstance(plugin_dir, (str, os.PathLike)):
        raise TypeError("plugin_dir must be a string or PathLike object")
    plugin_dir = os.fspath(plugin_dir)

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory")

    # Find the spec file (prefer YAML over JSON)
    spec_file = None
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in the directory")

    # Read the file contents
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:
        raise IOError(f"Error reading spec file '{spec_file}': {exc}") from exc

    if not content.strip():
        return {}

    # Parse the content
    try:
        if spec_file.lower().endswith((".yaml", ".yml")):
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML files")
            data = yaml.safe_load(content)
        else:
            data = json.loads(content)
    except Exception as exc:
        raise ValueError(f"Error parsing plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec root must be a dictionary")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten(value, new_key, sep=sep))
            else:
                items[new_key] = value
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = "CONFIG_PATH"
        # Only set if the variable is not already defined or is empty
        if not os.environ.get(env_var):
            try:
                default_path = os.path.join(os.getcwd(), "config.yaml")
            except Exception as e:
                # If we cannot determine a default path, skip setting
                raise RuntimeError(f"Unable to determine default config path: {e}") from e
            os.environ[env_var] = default_path
    except Exception as e:
        # Wrap any unexpected error in a RuntimeError to provide context
        raise RuntimeError(f"Failed to inject config environment variable: {e}") from e
